// Validate request, rate-limit per visitor, turn city names into IATA codes,
// and serve from cache when possible.
// Output: { response } to answer right away, or { url, ... } to call Travelpayouts.
// Cache, codes and rate-limit counters live in workflow static data, which n8n
// only persists for production (active) executions, not manual test runs.

// ── CONFIG ───────────────────────────────────────────────────────
const LIMIT_PER_IP = 30;                  // fare lookups per visitor...
const WINDOW_MS    = 10 * 60 * 1000;      // ...per 10 minutes
const CACHE_MS     = 6 * 60 * 60 * 1000;  // reuse a fare result for 6 hours
const CACHE_MAX    = 500;                 // max cached searches kept
const CODE_MAX     = 2000;                // max city-name -> code entries kept
const CURRENCIES   = ['USD', 'EUR', 'GBP', 'CAD', 'AUD', 'MXN', 'JPY'];
// ─────────────────────────────────────────────────────────────────

const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
store.hits = store.hits || {};
store.codes = store.codes || {};

const req = $input.first().json || {};
const body = req.body || {};
const headers = req.headers || {};
const now = Date.now();
const reply = (response) => [{ json: { response } }];

// Prune old counters and expired fare results.
for (const ip of Object.keys(store.hits)) {
  store.hits[ip] = store.hits[ip].filter((t) => now - t < WINDOW_MS);
  if (!store.hits[ip].length) delete store.hits[ip];
}
for (const k of Object.keys(store.cache)) {
  if (now - store.cache[k].at > CACHE_MS) delete store.cache[k];
}

// Rate limit by visitor IP.
const ip = String(
  headers['cf-connecting-ip'] ||
  String(headers['x-forwarded-for'] || '').split(',')[0] ||
  'unknown'
).trim();
const hits = store.hits[ip] || [];
if (hits.length >= LIMIT_PER_IP) {
  return reply({ ok: false, error: 'rate_limited', message: 'Too many fare lookups. Try again in a few minutes.', fallback: true });
}
hits.push(now);
store.hits[ip] = hits;

// Validate input.
const clean = (s, max) => String(s == null ? '' : s)
  .replace(/[\u0000-\u001f<>]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);
const bad = (message) => reply({ ok: false, error: 'bad_request', message });

const originIn = clean(body.origin, 80);
const destIn = clean(body.destination, 80);
if (originIn.length < 2) return bad('origin is required');
if (destIn.length < 2) return bad('destination is required');

// Dates: YYYY-MM (whole month) or YYYY-MM-DD, not in the past.
const today = new Date(now).toISOString().slice(0, 10);
function checkDate(v, name, required) {
  const s = clean(v, 10);
  if (!s) return required ? { error: name + ' is required (YYYY-MM or YYYY-MM-DD)' } : { value: '' };
  if (!/^\d{4}-(0[1-9]|1[0-2])(-(0[1-9]|[12]\d|3[01]))?$/.test(s)) return { error: name + ' must be YYYY-MM or YYYY-MM-DD' };
  const cmp = s.length === 7 ? today.slice(0, 7) : today;
  if (s < cmp) return { error: name + ' is in the past' };
  return { value: s };
}
const dep = checkDate(body.departDate, 'departDate', true);
if (dep.error) return bad(dep.error);
const ret = checkDate(body.returnDate, 'returnDate', false);
if (ret.error) return bad(ret.error);
if (ret.value && ret.value.slice(0, dep.value.length) < dep.value.slice(0, ret.value.length)) {
  return bad('returnDate is before departDate');
}

const cur = String(body.currency || '').toUpperCase();
const currency = CURRENCIES.includes(cur) ? cur : 'USD';
let limit = parseInt(body.limit, 10);
if (!(limit >= 1 && limit <= 10)) limit = 5;
const directOnly = body.directOnly === true || body.directOnly === 'true';

// Resolve a city name (or IATA code) to an IATA code via Travelpayouts
// autocomplete (public, no token). Results are remembered in static data.
async function resolve(term) {
  if (/^[A-Za-z]{3}$/.test(term)) return { code: term.toUpperCase(), name: term.toUpperCase() };
  const m = term.match(/\(([A-Za-z]{3})\)\s*$/);          // "New York (JFK)"
  if (m) return { code: m[1].toUpperCase(), name: term.replace(/\s*\([A-Za-z]{3}\)\s*$/, '') };
  const key = term.toLowerCase();
  if (store.codes[key]) return store.codes[key];
  let places;
  try {
    places = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://autocomplete.travelpayouts.com/places2',
      qs: { term, locale: 'en', 'types[]': ['city', 'airport'] },
      json: true,
      timeout: 8000,
    });
  } catch (e) {
    return null;
  }
  const list = Array.isArray(places) ? places : [];
  const hit = list.find((p) => p && p.type === 'city' && /^[A-Z]{3}$/.test(p.code)) ||
              list.find((p) => p && /^[A-Z]{3}$/.test(p.code));
  if (!hit) return null;
  const found = { code: hit.code, name: String(hit.name || term).slice(0, 80) };
  const keys = Object.keys(store.codes);
  if (keys.length >= CODE_MAX) keys.slice(0, keys.length - CODE_MAX + 1).forEach((k) => delete store.codes[k]);
  store.codes[key] = found;
  return found;
}

const origin = await resolve.call(this, originIn);
if (!origin) return reply({ ok: false, error: 'unknown_place', message: 'Could not find an airport for ' + originIn, fallback: true });
const destination = await resolve.call(this, destIn);
if (!destination) return reply({ ok: false, error: 'unknown_place', message: 'Could not find an airport for ' + destIn, fallback: true });
if (origin.code === destination.code) return bad('origin and destination are the same');

const cacheKey = [origin.code, destination.code, dep.value, ret.value, currency, limit, directOnly].join('|');
const hit = store.cache[cacheKey];
if (hit) return reply(Object.assign({}, hit.payload, { cached: true }));

const keys = Object.keys(store.cache);
if (keys.length >= CACHE_MAX) {
  keys.sort((a, b) => store.cache[a].at - store.cache[b].at)
    .slice(0, keys.length - CACHE_MAX + 1)
    .forEach((k) => delete store.cache[k]);
}

const params = new URLSearchParams({
  origin: origin.code,
  destination: destination.code,
  departure_at: dep.value,
  one_way: ret.value ? 'false' : 'true',
  direct: directOnly ? 'true' : 'false',
  sorting: 'price',
  unique: 'false',
  currency: currency.toLowerCase(),
  limit: String(limit),
  page: '1',
});
if (ret.value) params.set('return_at', ret.value);

return [{
  json: {
    cacheKey,
    currency,
    trip: { origin, destination, departDate: dep.value, returnDate: ret.value || null, directOnly },
    url: 'https://api.travelpayouts.com/aviasales/v3/prices_for_dates?' + params.toString(),
  },
}];

// Turn Travelpayouts prices_for_dates data into the small shape the site uses.
// These are cached fares (cheapest found by other users in roughly the last
// 48 hours), not live quotes, so the response says priceType: 'recent'.

// ── CONFIG ───────────────────────────────────────────────────────
const MARKER = '';   // your Travelpayouts partner ID (marker); not secret,
                     // it appears in public links. Empty = links still work, no commission.
// ─────────────────────────────────────────────────────────────────

const res = $input.first().json || {};
const prev = $('Validate & Resolve Airports').first().json;
const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
const reply = (response) => [{ json: { response } }];

// The HTTP node runs with "continue on error", so failures arrive as { error }.
if (res.error || res.success === false || !Array.isArray(res.data)) {
  return reply({ ok: false, error: 'upstream', message: 'Recent fares are unavailable right now.', fallback: true });
}

const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);
const iso = (v) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v) ? v : null);
const ddmm = (d) => d.slice(8, 10) + d.slice(5, 7);

// Booking link on Aviasales. Prefer the path Travelpayouts returns; otherwise
// build the standard /search/ORIGDDMMDESTDDMM1 link (1 = one adult).
function bookingUrl(f) {
  let url = null;
  if (typeof f.link === 'string' && /^\/(?!\/)/.test(f.link)) {
    url = 'https://www.aviasales.com' + f.link;
  } else if (typeof f.link === 'string' && f.link) {
    return null;   // unexpected link format: drop the fare rather than guess
  } else if (f.departure_at) {
    const back = f.return_at ? ddmm(f.return_at) : '';
    url = 'https://www.aviasales.com/search/' + prev.trip.origin.code + ddmm(f.departure_at) +
          prev.trip.destination.code + back + '1';
  }
  if (!url) return null;
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:' || u.hostname !== 'www.aviasales.com') return null;
    if (MARKER) u.searchParams.set('marker', MARKER);
    return u.toString();
  } catch (e) {
    return null;
  }
}

// Travelpayouts says which currency the prices are in; trust that over the request.
const currency = String(res.currency || prev.currency).toUpperCase();

const fares = res.data.map((f) => {
  const departAt = iso(f.departure_at);
  return {
    price: num(f.price),
    currency,
    airline: typeof f.airline === 'string' && /^[A-Z0-9]{2}$/.test(f.airline) ? f.airline : null,
    flightNumber: f.flight_number != null ? String(f.flight_number).slice(0, 8) : null,
    departAt,
    returnAt: iso(f.return_at),
    stops: num(f.transfers),
    returnStops: num(f.return_transfers),
    durationMinutes: num(f.duration),
    url: departAt ? bookingUrl(Object.assign({}, f, { departure_at: departAt, return_at: iso(f.return_at) })) : null,
  };
}).filter((f) => f.price != null && f.departAt && f.url);

const response = {
  ok: true,
  source: 'travelpayouts',
  priceType: 'recent',
  note: 'Cheapest fares found in the last 48 hours. Check the live price before booking.',
  fetchedAt: new Date().toISOString(),
  currency,
  trip: prev.trip,
  fares,
};

if (fares.length) store.cache[prev.cacheKey] = { at: Date.now(), payload: response };
return reply(response);
